import snapshot from "@/data/airtable-snapshot.json";

/**
 * Typed access to src/data/airtable-snapshot.json (generated by `npm run snapshot`
 * from the "SLB Investor ROI" Airtable base). Calculations live in Airtable;
 * this module only looks values up and shapes them for the charts.
 */

type Value = number | string | boolean | null | undefined | (number | string)[];
type Rec = Record<string, Value>;

export type YearRec = Rec & { Year: number };
export type QuarterRec = Rec & { "Quarter Label": string; Quarter: string; Year: number };
export type PeriodRec = Rec & { Period: string; "Sort Order": number; Years: number[] };
export type GoalRec = Rec & { Goal: string; Metric: string; Year: number };

export const years = snapshot.years as YearRec[];
export const quarters = snapshot.quarters as QuarterRec[];
export const periods = snapshot.periods as PeriodRec[];
export const goals = snapshot.goals as GoalRec[];

export const QUARTERS = ["Q1", "Q2", "Q3", "Q4"] as const;

/** Numeric field value, or null when blank/non-numeric */
export function num(rec: Rec | undefined, field: string): number | null {
  const v = rec?.[field];
  return typeof v === "number" && Number.isFinite(v) ? v : null;
}

export function yearRec(year: number): YearRec | undefined {
  return years.find((y) => y.Year === year);
}

export function quarterRec(year: number, quarter: string): QuarterRec | undefined {
  return quarters.find((q) => q.Year === year && q.Quarter === quarter);
}

/** Q1–Q4 values of a Quarters field for one year (null where not reported) */
export function quarterValues(year: number, field: string): (number | null)[] {
  return QUARTERS.map((q) => num(quarterRec(year, q), field));
}

/** Most recent quarter that has a value for `field` */
export function latestQuarter(field = "In-Year Lumber (MM BF)"): { year: number; quarter: number } {
  const withData = quarters.filter((q) => num(q, field) != null);
  const last = withData[withData.length - 1];
  return { year: last.Year, quarter: QUARTERS.indexOf(last.Quarter as (typeof QUARTERS)[number]) + 1 };
}

/** Index (1–4) of the last quarter with a value, or null if none */
export function topQuarter(values: (number | null | undefined)[]): number | null {
  for (let i = values.length - 1; i >= 0; i--) {
    if (values[i] != null) return i + 1;
  }
  return null;
}

export function goalValue(year: number, metric: string): number | null {
  return num(goals.find((g) => g.Year === year && g.Metric === metric), "Goal Value");
}

/** Dashboard bar groups (2012–15 … current year), in display order */
export function barPeriods(): PeriodRec[] {
  return periods.filter((p) => p["Sort Order"] < 99);
}

export function periodRec(name: string): PeriodRec | undefined {
  return periods.find((p) => p.Period === name);
}

/** Single-year periods are drawn as stacked quarters */
export function isSingleYear(p: PeriodRec): boolean {
  return p.Years.length === 1;
}

/** Years with a full annual record (spend reported) */
export function lastAnnualYear(): number {
  const annual = years.filter((y) => num(y, "SLB Investment ($MM)") != null);
  return annual[annual.length - 1].Year;
}

/** Bar row shared by the Demand Generated / Lumber / Panel / EWP charts */
export type VolumeRow = {
  label: string;
  totalFallback: number | null;
  q1: number | null;
  q2: number | null;
  q3: number | null;
  q4: number | null;
  totalBF_MM: number | null;
  /** Label value for period (non-quarterly) bars only. */
  volumeLabelAnnual: number | null;
  /** Total label, set only on the top (latest) quarter segment. */
  volumeLabelQ1: number | null;
  volumeLabelQ2: number | null;
  volumeLabelQ3: number | null;
  volumeLabelQ4: number | null;
  /** Goal callout, drawn above the top quarter segment. */
  goalLabelQ1: number | null;
  goalLabelQ2: number | null;
  goalLabelQ3: number | null;
  goalLabelQ4: number | null;
  showQuarters: boolean;
};

/**
 * Multi-year periods are one bar (the period's value from Airtable);
 * single-year periods are stacked quarters, totalled from the quarters
 * unless Airtable holds a published total for that period.
 */
export function volumeRows(opts: {
  periodField: string;
  quarterField: string;
  publishedField?: string;
  goalMetric?: string;
  skip?: string[];
}): VolumeRow[] {
  return barPeriods()
    .filter((p) => !opts.skip?.includes(p.Period))
    .map((p) => {
      const empty = {
        q1: null, q2: null, q3: null, q4: null,
        volumeLabelQ1: null, volumeLabelQ2: null, volumeLabelQ3: null, volumeLabelQ4: null,
        goalLabelQ1: null, goalLabelQ2: null, goalLabelQ3: null, goalLabelQ4: null,
      };
      if (!isSingleYear(p)) {
        const total = num(p, opts.periodField);
        return {
          ...empty, label: p.Period, totalFallback: total, totalBF_MM: total,
          volumeLabelAnnual: total, showQuarters: false,
        };
      }
      const year = p.Years[0];
      const qs = quarterValues(year, opts.quarterField);
      const top = topQuarter(qs);
      const published = opts.publishedField ? num(p, opts.publishedField) : null;
      const total = published ?? qs.reduce<number>((s, v) => s + (v ?? 0), 0);
      const goal = opts.goalMetric ? goalValue(year, opts.goalMetric) : null;
      const row: VolumeRow = {
        ...empty, label: p.Period, totalFallback: null,
        q1: qs[0], q2: qs[1], q3: qs[2], q4: qs[3],
        totalBF_MM: total, volumeLabelAnnual: null, showQuarters: true,
      };
      if (top) {
        row[`volumeLabelQ${top}` as "volumeLabelQ1"] = total;
        row[`goalLabelQ${top}` as "goalLabelQ1"] = goal;
      }
      return row;
    });
}

/** Row shared by the quarterly program charts (education, on-demand, projects, referrals) */
export type QuarterlyRow = {
  year: string;
  q1: number | null;
  q2: number | null;
  q3: number | null;
  q4: number | null;
  total: number;
  /** Year total, set only on the top (latest) quarter segment. */
  totalOnQ1: number | null;
  totalOnQ2: number | null;
  totalOnQ3: number | null;
  totalOnQ4: number | null;
  goal: number | null;
  /** Goal callout, set only on the top quarter segment. */
  goalOnQ1: number | null;
  goalOnQ2: number | null;
  goalOnQ3: number | null;
  goalOnQ4: number | null;
};

export function quarterlyRows(field: string, goalMetric?: string): QuarterlyRow[] {
  return programYears(field).map((year) => {
    const [q1, q2, q3, q4] = quarterValues(year, field);
    const total = [q1, q2, q3, q4].reduce<number>((s, v) => s + (v ?? 0), 0);
    const top = topQuarter([q1, q2, q3, q4]);
    const goal = goalMetric ? goalValue(year, goalMetric) : null;
    const row: QuarterlyRow = {
      year: String(year), q1, q2, q3, q4, total,
      totalOnQ1: null, totalOnQ2: null, totalOnQ3: null, totalOnQ4: null,
      goal,
      goalOnQ1: null, goalOnQ2: null, goalOnQ3: null, goalOnQ4: null,
    };
    if (top) {
      row[`totalOnQ${top}` as "totalOnQ1"] = total;
      row[`goalOnQ${top}` as "goalOnQ1"] = goal;
    }
    return row;
  });
}

/** Years with a converted-projects breakdown by type */
function convertedYears(): number[] {
  return years.filter((y) => num(y, "Converted: Light-Frame") != null).map((y) => y.Year);
}

export function convertedBySystem() {
  return convertedYears().map((year) => {
    const y = yearRec(year);
    const lightFrame = num(y, "Converted: Light-Frame") ?? 0;
    const hybridMtLf = num(y, "Converted: Hybrid MT/LF") ?? 0;
    const heavyMt = num(y, "Converted: Heavy/MT") ?? 0;
    return { year: String(year), lightFrame, hybridMtLf, heavyMt, total: lightFrame + hybridMtLf + heavyMt };
  });
}

const BUILDING_KEYS = ["multifamily", "commercial", "institutional", "warehouse", "other"] as const;
export type BuildingKey = (typeof BUILDING_KEYS)[number];

export function convertedByBuilding() {
  return convertedYears().map((year) => {
    const y = yearRec(year);
    const v = {
      multifamily: num(y, "Converted: Multifamily") ?? 0,
      commercial: num(y, "Converted: Commercial") ?? 0,
      institutional: num(y, "Converted: Institutional") ?? 0,
      warehouse: num(y, "Converted: Warehouse/Mfg") ?? 0,
      other: num(y, "Converted: Other") ?? 0,
    };
    // Top segment = last non-zero building type (gets the rounded corners and total label)
    const topKey: BuildingKey = [...BUILDING_KEYS].reverse().find((k) => v[k] > 0) ?? "multifamily";
    return { year: String(year), ...v, total: BUILDING_KEYS.reduce((s, k) => s + v[k], 0), topKey };
  });
}

/** Settings for the four volume charts (shared with the math checks in checks/) */
export const VOLUME_CHARTS = {
  demandGenerated: {
    periodField: "Demand Generated Calc (MM BF)",
    quarterField: "Demand Generated (MM BF)",
    goalMetric: "Demand Generated",
  },
  lumber: {
    periodField: "In-Year Lumber (MM BF)",
    quarterField: "In-Year Lumber (MM BF)",
    goalMetric: "In-Year Lumber",
    skip: ["2012–15"],
  },
  panel: {
    periodField: "Panel Calc (MM SF)",
    quarterField: "Panel (MM SF)",
    skip: ["2012–15"],
  },
  ewp: {
    periodField: "EWP (MM BF)",
    quarterField: "EWP (MM BF)",
    publishedField: "EWP Published (MM BF)",
    skip: ["2012–15"],
  },
} satisfies Record<string, Parameters<typeof volumeRows>[0]>;

/** Total Wood chart bar: lumber + panel + EWP, all in MM BF */
export type TotalWoodRow = {
  label: string;
  lumber: number;
  /** Panel in MM BF (Airtable "Panel (MM BF)"), so lumber + panel + EWP add up to the total. */
  panel: number;
  ewp: number;
  total: number;
};

export function totalWoodRows(): TotalWoodRow[] {
  return barPeriods()
    .filter((p) => p.Period !== "2012–15")
    .map((p) => {
      const lumber = num(p, "Total Wood Lumber Calc (MM BF)") ?? 0;
      const panel = num(p, "Panel Calc (MM BF)") ?? 0;
      const ewp = num(p, "EWP (MM BF)") ?? 0;
      return { label: p.Period, lumber, panel, ewp, total: lumber + panel + ewp };
    });
}

/** Demand Realized chart bar (MM BF): tail layers l1–l3 and direct l4, or a period total in l1 */
export type RealizedRow = {
  label: string;
  l1: number | null;
  l2: number | null;
  l3: number | null;
  l4: number | null;
  total: number;
  topSegment: "l1" | "l2" | "l3" | "l4";
};

/** Single-year bars show the tail layers; multi-year bars show the period total. */
export function demandRealizedRows(): RealizedRow[] {
  return barPeriods().map((p) => {
    if (!isSingleYear(p)) {
      const total = Math.round(num(p, "Demand Realized Total Calc (MM BF)") ?? 0);
      return { label: p.Period, l1: total, l2: null, l3: null, l4: null, total, topSegment: "l1" };
    }
    const seg = (field: string) => Math.round(num(p, field) ?? 0);
    const [l1, l2, l3, l4] = [seg("DR 25% 3-Yr Tail Calc"), seg("DR 25% 2-Yr Tail Calc"), seg("DR 50% Prior-Yr Tail Calc"), seg("DR Direct Calc")];
    return { label: p.Period, l1, l2, l3, l4, total: l1 + l2 + l3 + l4, topSegment: "l4" };
  });
}

/** Headline figures for the program impact pyramid (current year to date) */
export type PyramidFigures = {
  year: number;
  demandGenerated: number | null;
  projectsConverted: number | null;
  projectsInfluenced: number | null;
  /** Audience Engaged: TW net new contacts + WW new contacts + AWC attendees + WI completions + student/faculty engagements */
  individualContacts: number | null;
  /** AWC contact hours + TW CEUs (interim: 1 completion = 1 hour) + WW practitioner hours + WI learning hours */
  educationHours: number | null;
};

export function pyramidFigures(): PyramidFigures {
  const { year } = latestQuarter();
  const y = yearRec(year);
  return {
    year,
    demandGenerated: num(y, "Demand Generated (MM BF)"),
    projectsConverted: num(y, "Directly Influenced Projects (Year)"),
    projectsInfluenced: num(y, "Projects Calc"),
    individualContacts: num(y, "Audience Engaged"),
    educationHours: num(y, "Education Hours"),
  };
}

/** Years shown in the quarterly program charts (2024 onward) */
export function programYears(field: string): number[] {
  return [...new Set(quarters.filter((q) => num(q, field) != null).map((q) => q.Year))].sort();
}
